BEGIN;
DO $test$
DECLARE ceo uuid:='b8cbf27e-2391-4fb5-b061-f1488e8c3135'; pid uuid; other uuid; plan uuid; a uuid; w uuid; j uuid; token uuid:=gen_random_uuid(); k uuid:=gen_random_uuid(); stages jsonb; config jsonb; revision integer; n integer;
BEGIN
 PERFORM set_config('request.jwt.claim.sub',ceo::text,true);
 stages:='[{"title":"成果阶段","acceptance":"有完整成果"},{"title":"真实流程","acceptance":"实际走通关键路径"}]';
 pid:=public.create_company_project('PROJECT ROLLBACK FIXTURE','仅用于回滚验证','真实业务可用','输入到交付并验证失败恢复',stages,k);
 IF public.create_company_project('PROJECT ROLLBACK FIXTURE','仅用于回滚验证','真实业务可用','输入到交付并验证失败恢复',stages,k)<>pid THEN RAISE EXCEPTION 'Idempotency failed';END IF;
 BEGIN PERFORM public.record_project_check(pid,0,'final',NULL,'passed','Cannot skip');RAISE EXCEPTION 'Draft completion allowed';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 plan:=public.plan_company_project(pid,0);
 IF public.plan_company_project(pid,1)<>plan THEN RAISE EXCEPTION 'Duplicate planning';END IF;
 SELECT (result->>'current_job_id')::uuid INTO j FROM public.tasks WHERE id=plan;
 IF NOT EXISTS(SELECT 1 FROM public.messages m JOIN public.tasks t ON t.request_message_id=m.id WHERE t.id=j AND m.content LIKE '%输入到交付并验证失败恢复%') THEN RAISE EXCEPTION 'Full criteria missing';END IF;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=j;
 PERFORM public.complete_chat_reply(j,token,'Synthetic planning result','[]');
 PERFORM public.review_work_plan(plan,0,'{"mode":"direct","reason":"simple fixture","missing_information":[],"tasks":[{"title":"fixture task","agent_code":"COS","instruction":"fixture only","acceptance":"fixture output","after":[]}]}',true);
 SELECT id,(result->>'work_order_id')::uuid INTO a,w FROM public.tasks WHERE task_kind='plan_assignment' AND input->>'plan_id'=plan::text;
 config:=jsonb_build_array(jsonb_build_object('title','成果阶段','acceptance','有完整成果','task_ids',jsonb_build_array(a)),jsonb_build_object('title','真实流程','acceptance','实际走通关键路径','task_ids','[]'::jsonb));
 BEGIN PERFORM public.configure_company_project(pid,1,plan,'[{"title":"bad","acceptance":"bad","task_ids":[]}]');RAISE EXCEPTION 'Omitted assignment allowed';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.configure_company_project(pid,1,plan,jsonb_build_array(jsonb_build_object('title','bad','acceptance','bad','task_ids',jsonb_build_array(gen_random_uuid()))));RAISE EXCEPTION 'Foreign task allowed';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.configure_company_project(pid,1,plan,jsonb_build_array(config->0,config->0));RAISE EXCEPTION 'Duplicate binding allowed';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM public.configure_company_project(pid,1,plan,config);
 BEGIN PERFORM public.record_project_check(pid,1,'stage',0,'passed','Stale');RAISE EXCEPTION 'Stale revision allowed';EXCEPTION WHEN serialization_failure THEN NULL;END;
 BEGIN PERFORM public.record_project_check(pid,2,'stage',0,'passed','Unaccepted');RAISE EXCEPTION 'Unaccepted output allowed';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 SELECT (result->>'current_job_id')::uuid INTO j FROM public.tasks WHERE id=w;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=j;
 PERFORM public.complete_chat_reply(j,token,'Synthetic delivery','[]');
 PERFORM public.review_work_order(w,j,'accept','Rollback fixture');
 BEGIN PERFORM public.record_project_check(pid,2,'stage',1,'passed','Skipping stage');RAISE EXCEPTION 'Stage order bypass';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM public.record_project_check(pid,2,'stage',0,'passed','Verified fixture delivery');
 IF NOT EXISTS(SELECT 1 FROM public.project_checks WHERE project_id=pid AND snapshot->'task_versions'->0->>'job_id'=j::text AND actor_kind='ceo_manual') THEN RAISE EXCEPTION 'Evidence snapshot missing';END IF;
 PERFORM public.record_project_check(pid,3,'stage',1,'passed','Manual end user scenario evidence');
 BEGIN PERFORM public.record_project_check(pid,4,'final',NULL,'passed','No end-to-end');RAISE EXCEPTION 'Final gate bypass';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM public.record_project_check(pid,4,'integration',NULL,'passed','Actual full workflow evidence');
 PERFORM public.record_project_check(pid,5,'stage',0,'failed','New upstream issue');
 IF NOT EXISTS(SELECT 1 FROM public.company_projects cp WHERE cp.id=pid AND cp.stages->1->>'state'='pending' AND cp.integration_state='pending') THEN RAISE EXCEPTION 'Downstream checks not invalidated';END IF;
 PERFORM public.configure_company_project(pid,6,plan,config);
 PERFORM public.record_project_check(pid,7,'stage',0,'passed','Fixed upstream');
 PERFORM public.record_project_check(pid,8,'stage',1,'passed','Rechecked');
 PERFORM public.record_project_check(pid,9,'integration',NULL,'passed','Rechecked full scenario');
 PERFORM public.record_project_check(pid,10,'final',NULL,'passed','CEO business success confirmed');
 BEGIN PERFORM public.configure_company_project(pid,11,plan,config);RAISE EXCEPTION 'Accepted project mutable';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF (SELECT count(*) FROM public.project_checks WHERE project_id=pid)<>8 THEN RAISE EXCEPTION 'Check history changed';END IF;
 PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 BEGIN PERFORM public.record_project_check(pid,11,'final',NULL,'passed','Foreign actor');RAISE EXCEPTION 'Non CEO allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_table_privilege('authenticated','public.company_projects','UPDATE') OR has_table_privilege('authenticated','public.project_checks','INSERT') OR has_function_privilege('anon','public.plan_company_project(uuid,integer)','EXECUTE') OR has_function_privilege('service_role','public.record_project_check(uuid,integer,text,integer,text,text)','EXECUTE') THEN RAISE EXCEPTION 'Excess privileges';END IF;
END $test$;
SET LOCAL ROLE authenticated;
DO $rls$ BEGIN IF EXISTS(SELECT 1 FROM public.company_projects WHERE title='PROJECT ROLLBACK FIXTURE') OR EXISTS(SELECT 1 FROM public.project_checks WHERE evidence='CEO business success confirmed') THEN RAISE EXCEPTION 'RLS leak';END IF;END $rls$;
RESET ROLE;
ROLLBACK;
SELECT 'PASS: projects, idempotency, plan binding, scope, stages, stale revisions, end-to-end/final gates, immutable evidence, downstream invalidation, role restrictions and RLS; all fixtures rolled back' AS checks;
